WEB_END = """
var table_networks,table_ssid,row,createClickHandler;for(document.getElementById("ap_ssid").value=ap_ssid,document.getElementById("ap_pass").value=ap_pass,document.getElementById("ap_ip").value=ap_ip,document.getElementById("ap_mask").value=ap_mask,document.getElementById("eth_en").checked=eth_en,ipConfSelector("eth",document.getElementById("eth_select").value=eth_ip?"static":"dhcp"),document.getElementById("eth_ip").value=eth_ip,document.getElementById("eth_mask").value=eth_mask,document.getElementById("eth_gate").value=eth_gate,document.getElementById("wlan_en").checked=wlan_en,document.getElementById("heos_name").value=heos_name,document.getElementById("heos_user").value=heos_user,document.getElementById("heos_pass").value=heos_pass,table_networks=document.getElementById("tb_networks"),i=0;i<knownNetworks.length;i++)row=table_networks.insertRow(1),row.insertCell(0).innerHTML=knownNetworks[i][0],row.insertCell(1).innerHTML=knownNetworks[i][3]?"static":"dhcp",row.insertCell(2).appendChild(createDelButton()),insertHiddenCell(row,3,knownNetworks[i][1]),insertHiddenCell(row,4,knownNetworks[i][2]),insertHiddenCell(row,5,knownNetworks[i][3]);for(table_ssid=document.getElementById("tb_ssids"),i=0;i<ssids.length;i++){for(row=table_ssid.insertRow(1),j=0;j<ssids[i].length;j++)row.insertCell(j).innerHTML=ssids[i][j];createClickHandler=function(n){return function(){var t=n.getElementsByTagName("TD");document.getElementById("wlan_ssid").value=t[0].innerHTML;document.getElementById("wlan_bssid").value=t[1].innerHTML}};row.onclick=createClickHandler(row)}
</script></body></html>
"""

def getWeb(heos, link, networks):
    result = ""

    result += 'var ap_ssid="{}";'.format(link.AP_ssid)
    result += 'var ap_pass="{}";'.format(link.AP_pass)
    ip = fileman.stringtoip(link.AP_conf)
    result += 'var ap_ip="{}";'.format(ip[0] if ip else "")
    result += 'var ap_mask="{}";'.format(ip[1] if ip else "")
    result += 'var eth_en={};'.format("true" if link.ETH_en else "false")
    ip = fileman.stringtoip(link.ETH_conf)
    result += 'var eth_ip="{}";'.format(ip[0] if ip else "")
    result += 'var eth_mask="{}";'.format(ip[1] if ip else "")
    result += 'var eth_gate="{}";'.format(ip[2] if ip else "")
    result += 'var wlan_en={};'.format("true" if link.WLAN_en else "false")
    result += 'var heos_name="{}";'.format(heos.name)
    result += 'var heos_user="{}";'.format(heos.user)
    result += 'var heos_pass="{}";'.format(heos.password)
    result += 'var ssids={};'.format(link.WLAN_profiles)
    result += 'var knownNetworks={};'.format(networks)

    return WEB_START + result + WEB_END

